import requests
import logging
def task_func(repo_url: str) -> dict:
    if not repo_url:
        raise ValueError("Repository URL must be a non-empty string.")

    headers = {"User-Agent": "Mozilla/5.0"}

    try:
        response = requests.get(repo_url, headers=headers, timeout=10)

        if not response.ok:
            if response.status_code == 403 and response.headers.get("X-RateLimit-Remaining") == "0":
                raise requests.exceptions.HTTPError("GitHub API rate limit exceeded. Please try again later.")
            else:
                raise requests.exceptions.HTTPError(f"HTTP error {response.status_code}: {response.reason}")

        repo_info = response.json()

        threshold = 100
        open_issues = repo_info.get("open_issues_count", 0)
        if open_issues > threshold:
            logging.warning(f"Repository has {open_issues} open issues, which exceeds the threshold of {threshold}.")

        return repo_info

    except requests.exceptions.HTTPError:
        raise
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Failed to fetch repository data: {e}")

